1	package darksafe
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"io"
8		"math"
9		"math/big"
10		"regexp"
11		"sort"
12		"strconv"
13		"strings"
14		"unicode"
15		"unicode/utf16"
16		"unicode/utf8"
17	)
18	
19	// Point 是一条序列上某个时间戳的采样值。
20	type Point struct {
21		Timestamp int64   `json:"timestamp"`
22		Value     float64 `json:"value"`
23	}
24	
25	// SeriesView 是结果输出用的一条序列视图，标签按键升序呈现。
26	type SeriesView struct {
27		Name   string            `json:"name"`
28		Labels map[string]string `json:"labels"`
29		Points []Point           `json:"points"`
30	}
31	
32	// QuerySeries 是查询结果中的一条序列：完整身份与区间内点的个数及算术平均值。
33	type QuerySeries struct {
34		Name    string            `json:"name"`
35		Labels  map[string]string `json:"labels"`
36		Count   int               `json:"count"`
37		Average float64           `json:"average"`
38	}
39	
40	// QueryResult 是一次区间均值查询成功后的结果，只读，不改变存储。
41	type QueryResult struct {
42		Status string        `json:"status"`
43		Op     string        `json:"op"`
44		Series []QuerySeries `json:"series"`
45	}
46	
47	// QueryPointsSeries 是采样明细查询结果中的一条序列：完整身份与区间内
48	// 按时间戳升序排列的采样点，不附带点数或平均值。
49	type QueryPointsSeries struct {
50		Name   string            `json:"name"`
51		Labels map[string]string `json:"labels"`
52		Points []Point           `json:"points"`
53	}
54	
55	// QueryPointsResult 是一次区间采样明细查询（op 为 query_points）成功后的结果，
56	// 只读，不改变存储。
57	type QueryPointsResult struct {
58		Status string              `json:"status"`
59		Op     string              `json:"op"`
60		Series []QueryPointsSeries `json:"series"`
61	}
62	
63	// Window 是固定时间窗口统计中的一个窗口：[Start,End] 闭区间（含首尾毫秒）内
64	// 已成功保存的点的个数与算术平均值。空窗口不会出现——只有实际有点的窗口才列出。
65	type Window struct {
66		Start   int64   `json:"start"`
67		End     int64   `json:"end"`
68		Count   int     `json:"count"`
69		Average float64 `json:"average"`
70	}
71	
72	// QueryWindowsSeries 是固定窗口均值查询结果中的一条序列：完整身份与按窗口起点
73	// 升序排列的窗口统计，空窗口不补零。
74	type QueryWindowsSeries struct {
75		Name    string            `json:"name"`
76		Labels  map[string]string `json:"labels"`
77		Windows []Window          `json:"windows"`
78	}
79	
80	// QueryWindowsResult 是一次固定时间窗口均值查询（op 为 query_windows）成功后的
81	// 结果，只读，不改变存储。
82	type QueryWindowsResult struct {
83		Status string               `json:"status"`
84		Op     string               `json:"op"`
85		Series []QueryWindowsSeries `json:"series"`
86	}
87	
88	// BatchResult 是一批采样点写入成功后的结果。
89	type BatchResult struct {
90		Status     string       `json:"status"`
91		Added      int          `json:"added"`
92		Duplicates int          `json:"duplicates"`
93		Series     []SeriesView `json:"series"`
94	}
95	
96	// SeriesRef 标识一条序列：指标名加完整标签集合。
97	// 缺少某个标签与该标签值为空字符串属于不同序列。
98	type SeriesRef struct {
99		Name   string            `json:"name"`
100		Labels map[string]string `json:"labels"`
101	}
102	
103	// Conflict 描述同一序列同一时间戳已存在不同的值。
104	type Conflict struct {
105		Series    SeriesRef `json:"series"`
106		Timestamp int64     `json:"timestamp"`
107		Existing  float64   `json:"existing"`
108		Submitted float64   `json:"submitted"`
109	}
110	
111	// LineError 是一行（一批）输入失败后的结构化结果。
112	// Line 由命令入口按从 1 开始的行号填入；Index 为采样点在批次内从 1 开始的位置，
113	// 整行 JSON 无法解析或不是数组时 Index 为零并省略。
114	type LineError struct {
115		Status   string    `json:"status"`
116		Line     int       `json:"line,omitempty"`
