172	// labelPair 是标签键值对字典序比较的单元。
173	type labelPair struct {
174		Key, Value string
175	}
176	
177	func sortedPairs(labels map[string]string) []labelPair {
178		keys := sortedKeys(labels)
179		pairs := make([]labelPair, len(keys))
180		for i, k := range keys {
181			pairs[i] = labelPair{Key: k, Value: labels[k]}
182		}
183		return pairs
184	}
