	res := mustOK(t, store, `[{"name":"m","timestamp":1,"value":1.0,"labels":{"b":"2","a":"1"}}]`)
	if res.Added != 0 || res.Duplicates != 1 || len(res.Series) != 1 {
		t.Fatalf("got %+v, want single duplicate against same series", res)
	}
}

